public class PrimeRange {
    public static void main(String[] args) {

        int start = 0;
        int end = 30;

        for(int num = start; num <= end; num++){

            if (num < 2) continue;

            boolean prime = true;
            for(int i = 2; i < num; i++){
                if(num % i == 0) prime = false;
            }

            if (prime) System.out.print(num + " ");
        }
    }
}

public class DiagonalMatrix {
    public static void main(String[] args) {

        int[][] m = {
            {1, 2, 3},
            {4, 5, 6},
            {7, 8, 9}
        };

        int n = m.length;

        int diagonalSum = 0;
        int antiDiagonalSum = 0;

        for (int i = 0; i < n; i++) {
            diagonalSum = diagonalSum + m[i][i];
            antiDiagonalSum =  antiDiagonalSum + m[i][n-i-1];
        }

        System.out.println("Main diagonal : " + diagonalSum);
        System.out.println("Anti diagonal : " + antiDiagonalSum);
    }
}

public class Transpose {
    public static void main(String[] args) {

        int[][] m = {
            {1, 2, 3},
            {4, 5, 6}
        };

        int rows = m.length;
        int cols = m[0].length;

        int[][] t = new int[cols][rows];


        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                t[j][i] = m[i][j];
            }
        }

        System.out.println("Transpose Matrix : ");

        for (int i = 0; i < cols; i++) {
            for (int j = 0; j < rows; j++) {
                System.out.print(t[i][j] + " ");
            }
            System.out.println();
        }
    }
}

import java.util.HashMap;

public class AnagramCheck {

    static HashMap<Character, Integer> count (String s) {

        HashMap<Character,Integer> map = new HashMap<>();

        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);
            map.put(ch, map.getOrDefault(ch, 0) +1);
        }

        return map;
    }

    public static void main(String[] args) {
        String s1 = "listen";
        String s2 = "silent";

        boolean anagram = count(s1).equals(count(s2));
        System.out.println("Anagram: " + anagram);
    }


}

