public class CountCharacters {
    public static void main(String[] args) {

        String text = "Dhaka 1000 is a City";

        int vowels = 0;
        int consonents = 0;
        int digits = 0;


        for (int i = 0; i < text.length(); i++) {
            char ch = text.charAt(i);

            ch = Character.toLowerCase(ch);

            if (ch == 'a' || ch == 'e' || ch == 'i' || ch == 'o' || ch == 'u') {
                vowels++;
            } else if(ch >= 'a' && ch <= 'z'){
                consonents++;
            } else if(ch >= '0' && ch <= '9'){
                digits++;
            }
        }

        System.out.println("Vowels     : " + vowels);
        System.out.println("Consonants : " + consonents);
        System.out.println("Digits     : " + digits);
    }
}

public class ReverseWords {
    public static void main(String[] args) {

        String text = "University Examination 2026";

        String[] words = text.split(" ");

        for (int i = 0; i < words.length; i++) {

            String word = words[i];
            String rev = "";

            // index 0 থেকে শুরু, তাই শেষ অক্ষরের index = length() - 1
            // শুধু length() দিলে ওই index-এ কিছু নেই → StringIndexOutOfBoundsException
            for (int j = word.length() - 1; j >= 0; j--) {
                rev = rev + word.charAt(j);
            }

            System.out.print(rev + " ");
        }
    }
}

public class BinarySearch {

    public static void main(String[] args) {

        int[] arr = {2, 5, 8, 12, 16, 23, 38, 56, 72, 91};
        int target = 23;

        int low = 0;
        int high = arr.length - 1;
        int found = -1;

        while (low <= high) {

            int mid = low + (high - low) / 2;

            if (arr[mid] == target) {
                found = mid;
                break;
            } else if (arr[mid] < target) {
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }

        System.out.println("Target : " + target);
        System.out.println("Index  : " + found);
    }

}

public class BubbleSort {
    public static void main(String[] args) {
        int[] arr = {45, 12, 78, 23, 6};

        int n = arr.length;

        for(int i = 0; i < n-1 ; i++){
            for(int j = 0; j < n-1-i; j++){

                if(arr[j] > arr[j+1]){
                    int temp = arr[j];
                    arr[j] = arr[j+1];
                    arr[j+1] = temp;
                }
            }
        }

        System.out.print("Sorted: ");
        for (int i = 0; i < n; i++) {
            System.out.print(arr[i] + " ");
        }
    }
}

import java.util.HashSet;

public class CommonElements {
    public static void main(String[] args) {
        int[] a = {4, 9, 5, 1, 7};
        int[] b = {9, 4, 9, 8, 4};

        HashSet<Integer> inB = new HashSet<>();
        for(int j = 0; j < b.length; j++){
            inB.add(b[j]);
        }

        HashSet<Integer> common = new HashSet<>();

        for(int i = 0; i < a.length; i++){
            if(inB.contains(a[i]))
                common.add(a[i]);
        }

        System.out.println("Common values : " + common);
    }
}

