public class SecondLargest {

    public static void main(String[] args) {

         int[] arr = {12, 35, 1, 10, 35, 2};

         int largest = arr[0];

         for(int i = 0; i < arr.length; i++){
            if(arr[i] > largest) largest = arr[i];
         }

         int secondLargest = -1;

         for(int i = 0; i < arr.length; i++){
            if(arr[i] > secondLargest && arr[i] != largest)
                secondLargest = arr[i];
